export function sourceTypeFromBackend(sourceId: string | null | undefined, contentType: string | null | undefined): SourceType {
  if (sourceId && SOURCE_TYPE_BY_ID[sourceId]) return SOURCE_TYPE_BY_ID[sourceId];
  switch (contentType) {
    case "owner":
      return "forum";
    case "expert":
      return "review";
    case "press":
      return "competitor_official";
    case "news":
      return "news";
    case "bmw_internal":
      return "bmw_feedback";
    case "reference":
      return "trend_report";
    default:
      return "news";
  }
}

export function agentFromBackend(evidenceRole: string | null | undefined, sourceId: string | null | undefined, kind: string): Agent {
  if (sourceId?.startsWith("bmw_") || sourceId === "option_list") return "bmw_data";
  if (evidenceRole === "competitor") return "competitor";
  if (kind === "trend") return "trends";
  if (kind === "innovation") return "innovation_scout";
  return "customer_public";
}

/** Display-only source tier (never part of the score: CLAUDE.md rejects a confidence axis). */
export function trustFromBackend(sourceId: string | null | undefined, contentType: string | null | undefined): Trust {
  if (sourceId?.startsWith("bmw_") || sourceId === "option_list") return "A";
  if (contentType === "expert" || contentType === "reference") return "B";
  if (contentType === "owner" || contentType === "news") return "C";
  return "D";
}

export function powertrainFromBackend(p: string | null | undefined): "ICE" | "PHEV" | "BEV" | "unknown" {
  return p === "ICE" || p === "PHEV" || p === "BEV" ? p : "unknown";
}

// ---------- Citations ----------
/** `[signal:<uuid>]` -> `[<uuid>]`, the form the UI's markdown links to the case page. */
export const rewriteCitations = (text: string) =>
  text
    .replace(/\[signal:([0-9a-f-]{36})\]/gi, "[$1]")
    // PM context (brief, stance, answers, notes, feedback) is named, not linked to a signal.
    .replace(/\[context:([a-z_]+):([^\]\s]+)\]/g, (_, type: string, id: string) => `(${CONTEXT_LABEL[type] ?? "PM context"}${/^[A-Z]+-/.test(id) ? ` ${id}` : ""})`);

const CONTEXT_LABEL: Record<string, string> = { series_brief: "series brief", case_stance: "PM stance", open_question: "question", meeting_note: "meeting note", requirement_feedback: "feedback", comment: "comment" };
import { endpoints, type BodyOf, type EndpointName, type QueryOf, type ResponseOf } from "@/contracts";
import { getUserId } from "@/lib/session";

/**
 * Typed client for the REST contract. The UI only talks to the backend through
 * this function. Base URL: NEXT_PUBLIC_API_BASE_URL (default "/api" = the mock).
 */
const BASE = process.env.NEXT_PUBLIC_API_BASE_URL ?? "/api";

export class ApiRequestError extends Error {
  constructor(
    public status: number,
    message: string,
    public details?: unknown,
  ) {
    super(message);
  }
}

export interface CallOptions<N extends EndpointName> {
  params?: Record<string, string>;
  query?: [QueryOf<N>] extends [never] ? never : Partial<Record<keyof QueryOf<N>, string | number | boolean | undefined>>;
  body?: [BodyOf<N>] extends [never] ? never : BodyOf<N>;
}

export function buildPath<N extends EndpointName>(name: N, opts: CallOptions<N> = {}) {
  const def = endpoints[name];
  const path = def.path.replace(/:([a-zA-Z]+)/g, (_, k: string) => {
    const v = opts.params?.[k];
    if (v === undefined) throw new Error(`Missing path param "${k}" for ${name}`);
    return encodeURIComponent(v);
  });
  const q = Object.entries((opts.query ?? {}) as Record<string, unknown>).filter(([, v]) => v !== undefined && v !== "");
  return path + (q.length ? "?" + new URLSearchParams(q.map(([k, v]) => [k, String(v)])).toString() : "");
}

export async function api<N extends EndpointName>(name: N, opts: CallOptions<N> = {}): Promise<ResponseOf<N>> {
  const def = endpoints[name];
  const headers: Record<string, string> = { "content-type": "application/json" };
  const user = getUserId();
  if (user) headers["x-user-id"] = user;
  const res = await fetch(BASE + buildPath(name, opts), {
    method: def.method,
    headers,
    body: "body" in def ? JSON.stringify(opts.body ?? {}) : undefined,
  });
  const json = await res.json().catch(() => null);
  if (!res.ok) throw new ApiRequestError(res.status, json?.error ?? `Request failed (${res.status})`, json?.issues);
  return json as ResponseOf<N>;
}
"use client";

import { useMutation, useQuery, useQueryClient, type UseQueryOptions } from "@tanstack/react-query";
import { toast } from "sonner";
import type { EndpointName, ResponseOf } from "@/contracts";
import { api, type CallOptions } from "./client";

/** Query any GET endpoint of the contract. */
export function useApi<N extends EndpointName>(
  name: N,
  opts: CallOptions<N> = {},
  options: Omit<UseQueryOptions<ResponseOf<N>>, "queryKey" | "queryFn"> = {},
) {
  return useQuery<ResponseOf<N>>({
    queryKey: [name, opts.params ?? null, opts.query ?? null, opts.body ?? null],
    queryFn: () => api(name, opts),
    ...options,
  });
}

/**
 * Call a mutating endpoint. On success every active query is refetched
 * (simple and always consistent for a demo-sized dataset).
 */
export function useApiMutation<N extends EndpointName>(name: N, config: { success?: string | ((data: ResponseOf<N>) => string); silent?: boolean } = {}) {
  const qc = useQueryClient();
  return useMutation<ResponseOf<N>, Error, CallOptions<N>>({
    mutationFn: (opts) => api(name, opts),
    onSuccess: async (data) => {
      await qc.invalidateQueries();
      if (config.success) toast.success(typeof config.success === "function" ? config.success(data) : config.success);
    },
    onError: (e) => {
      if (!config.silent) toast.error(e.message);
    },
  });
}
import { changeAmbitionLabel, costSensitivityLabel, marketLabel, positioningLabel, releaseLabel, targetCustomerLabel, type BriefFieldKey, type BriefValues, type Market, type ReleaseTarget } from "@/contracts";

/**
 * Where the onboarding form starts for questions nobody answered yet (a brief pre-filled
 * from data holds only market weights, the protect list and the don't-fight-on list).
 * These are a starting point, never stored until the PM saves the brief.
 */
export const BRIEF_START: BriefValues = {
  thesis: "",
  targetCustomer: { who: "both", positioning: "premium" },
  marketWeights: { EU: 0.25, US: 0.25, CN: 0.25, RoW: 0.25 },
  changeAmbition: { level: "balanced", innovationSlots: 3 },
  protectList: [],
  dontFightOn: [],
  givens: { platform: "", sop: "", frozen: [], openReleases: ["next_gen", "lci", "ota"], cycle: "WLTP" },
  costEnvelope: { sensitivity: "medium", perCarBand: "" },
};

/** Short human text for a brief value (brief page, conflicts, proposals). UI-only. */
export function showBriefValue(field: BriefFieldKey | string, v: unknown): string {
  if (v === undefined || v === null) return "—";
  const x = v as Record<string, unknown>;
  switch (field) {
    case "targetCustomer":
      return `${targetCustomerLabel[x.who as "both"]} · ${positioningLabel[x.positioning as "base"]}`;
    case "changeAmbition":
      return `${changeAmbitionLabel[x.level as "balanced"]}, ${x.innovationSlots} innovation${x.innovationSlots === 1 ? "" : "s"}`;
    case "costEnvelope":
      return `${costSensitivityLabel[x.sensitivity as "low"]} sensitivity · ${x.perCarBand}`;
    case "marketWeights":
      return (Object.entries(x) as [Market, number][])
        .filter(([, w]) => Number(w) > 0)
        .sort((a, b) => Number(b[1]) - Number(a[1]))
        .map(([k, w]) => `${marketLabel[k]} ${Math.round(Number(w) * 100)}%`)
        .join(" · ");
    case "givens":
      return `${x.platform ? `${x.platform}; ` : ""}SOP ${x.sop}; frozen: ${(x.frozen as string[]).join(", ") || "nothing"}; open: ${(x.openReleases as ReleaseTarget[]).map((r) => releaseLabel[r]).join(", ")}; cycle ${x.cycle}`;
    default:
      return Array.isArray(v) ? v.join(" · ") : String(v);
  }
}
/**
 * Demo helpers owned by the UI (prefill texts for the stage demo).
 * Not part of the API contract.
 */

/** Strategy docs a PM can paste during onboarding; the AI turns them into brief proposals. */
export const sampleStrategyDocs: Record<string, { title: string; text: string }> = {
  "u-wei": {
    title: "5 Series Li China strategy 2030 (excerpt)",
    text: `5 Series Li successor, China market strategy (draft for the product line meeting)

Thesis: In China the 5 Series Li must win buyers from NIO, Xiaomi and Li Auto: digital experience and rear-seat comfort first, driving dynamics second.

Target customer: we need conquest buyers from local EV brands, not only BMW owners renewing their lease. Tier stays premium.

Ambition: this is a revolution for China, not an evolution: we want 4 real innovations the customer notices in the showroom.

Givens: range targets are set in CLTC, never WLTP. The mid-life update is still open for China-specific content.

Cost: low sensitivity, local sourcing in Shenyang allows richer standard equipment.

Do not fight on: entry-level price.`,
  },
