490	    const scope = answers.find((a) => a.key === "scope")?.value === "variant" ? (input.region === "global" ? "RoW" : input.region) : "global";
491	    const release = answers.find((a) => a.key === "release")?.value;
492	    const global = siblings.find((r) => r.marketScope === "global" && r.status !== "rejected");
493	    const created = await send<Row[]>(user, "POST", `/cases/${encodeURIComponent(params.id)}/vehicles/${vehicle}/requirements/draft`, {
494	      answers,
495	      market_scope: scope,
496	      release_target: release ? releaseToBackend(release as Requirement["releaseTarget"]) : undefined,
497	      variant_of: scope !== "global" ? (global?.id ?? null) : null,
498	    });
499	    if (!created.length) throw new ApiError(409, `A ${scope === "global" ? "global" : scope} requirement already exists for this case.`);
500	    if (input.stance?.pendingShape.length) await send(user, "PUT", `/cases/${encodeURIComponent(params.id)}/stance`, { overrides: input.stance.overrides, override_reasons: input.stance.overrideReasons, evidence_takes: input.stance.evidenceTakes, inside: input.stance.inside, ambition: input.stance.ambition, pending_shape: [] });
501	    const out = created.map((r) => requirementFromBackend({ ...r, car_area: c.carArea, topic_id: c.topicId }, user.id));
502	    for (const r of out) await runCheck(user, r, "After drafting", x);
503	    return out;
504	  },
