552	    const check = row.check && row.check.version === row.body_version ? checkFromBackend(row.check) : await runCheck(user, requirement, "On opening the requirement", x);
553	    return {
554	      requirement,
555	      case: { ...c, signalIds: signals.map((s) => s.id) },
