581	    return buildReplay(d, b.requirement);
582	  },
583	  patchRequirement: async ({ user, params, body }) => {
584	    const { row, requirement, x } = await loadRequirement(user, params.id);
585	    const id = encodeURIComponent(params.id);
586	    // The car area always follows the case's topic; change depth and the edited argument sheet have no backend field yet.
587	    const { manualRank, carArea: _carArea, changeDepth: _changeDepth, argumentMd: _argumentMd, ...content } = body.patch;
