614	    const stored = await send(user, "POST", `/requirements/${id}/feedback`, { source: body.from, text: body.text, response: body.response, rationale: body.rationale, signal_ids: body.signalIds ?? [] });
615	    const fb: FeedbackEntry = feedbackFromBackend(stored);
616	    // The next version is proposed, never applied: a minimal patch from the feedback and the PM's response.
