620	    const [proposal] = await saveProposals(user, [{ objectType: "requirement", objectId: params.id, source: "feedback", kind: "new_version", summary, changes: [{ field: "version", before: current, after: draft }], citations: fb.signalIds }], "drafter");
621	    await send(user, "PATCH", `/requirements/feedback/${fb.id}`, { proposal_id: proposal.id });
