686	  exportRequirements: async ({ user, body }) => {
687	    const x = await ctx(user);
688	    const [rows, cases] = await Promise.all([reqBoard(user, x.profileId), board(user, x.profileId)]);
689	    const byCase = new Map(cases.map((c) => [c.id, c]));
690	    const list = rows.filter((r) => r.vehicle === body.series && (body.requirementIds ? body.requirementIds.includes(r.id) : ["signed_off", "planned", "exported"].includes(r.status)));
691	    const out = list.map((row) => {
692	      const r = requirementFromBackend(row, x.owner(row.vehicle));
693	      const c = byCase.get(row.case_id);
694	      return {
695	        ID: r.id,
696	        Summary: r.title,
697	        Description: r.description,
698	        Category: r.carArea,
699	        Market: r.marketScope,
700	        Release: r.releaseTarget,
701	        Priority: row.rank,
702	        Score: row.rank_score ?? "",
703	        "Evidence level": r.evidenceLevel,
704	        Metrics: r.metrics.map((m) => `${m.question}: ${m.target} (${m.basis})`).join(" | "),
705	        "Acceptance criteria": r.acceptanceCriteria.join(" | "),
706	        Assumptions: r.assumptions.join(" | "),
