716	    });
717	    let content: string;
718	    if (body.format === "json") content = JSON.stringify(out, null, 2);
719	    else {
720	      const cols = out[0] ? Object.keys(out[0]) : ["ID"];
721	      const esc = (v: unknown) => `"${String(v).replace(/"/g, '""')}"`;
722	      content = [cols.join(","), ...out.map((r) => cols.map((k) => esc(r[k as keyof typeof r])).join(","))].join("\n");
723	    }
724	    // The hand-over moves every planned requirement to exported (each one audited by the backend).
725	    for (const r of list.filter((r) => r.status === "planned")) await send(user, "POST", `/requirements/${encodeURIComponent(r.id)}/transition`, { action: "export", rationale: `Exported to Codebeamer (${body.format})` });
726	    const day = new Date().toISOString().slice(0, 10);
727	    return { filename: `requirements_${body.series}_${day}.${body.format === "json" ? "json" : "csv"}`, mime: body.format === "json" ? "application/json" : "text/csv", content, count: out.length };
728	  },
729	  requirementDeck: async ({ user, params }) => {
730	    const x = await ctx(user);
731	    const series = params.series as Series;
732	    const [rows, plan, profiles] = await Promise.all([reqBoard(user, x.profileId), get(user, `/plans/${series}`), profilesOf(user, x.ws.config_id)]);
733	    const weights = weightsFromBackend((profiles.find((p) => p.id === x.profileId) ?? profiles[0]).case_weights);
734	    const total = FactorKeys.options.reduce((s, f) => s + (weights[f] ?? 0), 0) || 1;
735	    const sev = { defect: 0, difficult_to_use: 1, wish: 2, none: 3 } as const;
736	    const list = rows.filter((r) => r.vehicle === series && ["signed_off", "planned", "exported"].includes(r.status));
737	    const slides = [];
738	    for (const row of list) {
739	      const { row: full, requirement: r } = await loadRequirement(user, row.id, x);
740	      const { page, case: c } = await loadCase(user, r.caseId, x);
741	      const signals = await caseSignals(user, r.caseId, series);
742	      const quotes = signals
743	        .filter((s) => s.sourceType === "bmw_feedback" && s.kind !== "like")
744	        .sort((a, b) => Number(a.kind !== "complaint") - Number(b.kind !== "complaint") || sev[a.severity] - sev[b.severity])
745	        .slice(0, 3)
746	        .map((s) => {
747	          const text = (s.quoteEn ?? s.quote).replace(/\s+/g, " ").trim();
748	          return { ref: s.id, market: s.market, text: text.length > 240 ? `${text.slice(0, 237).replace(/\s+\S*$/, "")}…` : text };
749	        });
750	      const comp = signals.filter((s) => s.kind === "competitor_fact").slice(0, 3);
751	      const name = (actor: string) => x.all.find((u) => u.id === actor.split(":").pop())?.name ?? actor;
752	      const decisions = [...(full.decisions as Row[]), ...(page.decisions as Row[]).filter((d) => !d.vehicle || d.vehicle === series)]
753	        .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)))
754	        .slice(0, 5)
755	        .map((d) => ({ at: String(d.created_at), actor: name(d.actor), action: String(d.action).replace("_", " "), rationale: d.rationale ?? undefined }));
756	      const issues = ((full.check?.issues ?? []) as Row[]).filter(() => full.check?.version === full.body_version);
757	      const red = issues.filter((i) => i.severity === "red").length;
758	      slides.push({
759	        requirementId: r.id,
760	        rank: row.rank,
761	        score: Number(row.rank_score ?? 0),
762	        title: r.title,
763	        description: r.description,
764	        status: r.status,
765	        release: r.releaseTarget,
766	        marketScope: r.marketScope,
767	        evidenceLevel: r.evidenceLevel,
768	        metrics: r.metrics,
769	        quotes,
770	        factors: FactorKeys.options.map((f) => {
771	          const weight = (weights[f] ?? 0) / total;
772	          return { factor: f, value: c.factors[f] ?? 0, weight: Math.round(weight * 1000) / 1000, contribution: Math.round(weight * (c.factors[f] ?? 0) * 1000) / 1000 };
773	        }),
774	        competitor: comp.length ? comp.map((s) => `${s.competitor ?? s.sourceName}: ${s.summary}`) : c.figures.competitorOffer,
775	        decisions,
776	        openIssues: { red, amber: issues.length - red },
777	        provenance: provenanceCounts(r),
778	        version: r.version,
779	        caseId: c.id,
780	        caseTitle: c.title,
781	        ownerName: x.all.find((u) => u.id === r.ownerId)?.name ?? r.ownerId,
782	      });
783	    }
784	    const now = new Date().toISOString();
785	    return { filename: `engineering-round_${series}_${now.slice(0, 10)}.pptx`, series, successorName: plan.successor_name, generatedAt: now, slides };
786	  },
787	
788	  // Conversation
789	  messages: async ({ user, params }) => {
790	    const [rows, proposals] = await Promise.all([get<Row[]>(user, `/chat/${params.type}/${encodeURIComponent(params.id)}`), get<Row[]>(user, "/proposals", { object_type: params.type, object_id: params.id })]);
791	    return rows.map((m) => chatFromBackend(m, proposals, () => "Signal"));
792	  },
793	  postMessage: async ({ user, params, body }) => {
794	    const type = params.type as "case" | "requirement";
795	    const id = encodeURIComponent(params.id);
796	    const x = await ctx(user);
797	    const caseId = type === "requirement" ? (await loadRequirement(user, params.id, x)).row.case_id : params.id;
798	    const { page, case: c, vehicle } = await loadCase(user, caseId, x);
799	    const signals = await caseSignals(user, caseId, vehicle);
800	    const label = signalLabel(signals);
801	    const full = { ...c, signalIds: signals.map((s) => s.id) };
802	    const say = (content: string) => send(user, "POST", `/chat/${type}/${id}/messages`, { role: "pm", content, segment: body.segment });
803	
804	    if (body.segment) {
805	      // "Ask the segment": answered only from that segment's BMW verbatims; no evidence means it says so.
806	      const seg = await segmentReply(mini({ signals }), full, type, params.id, body.segment);
807	      if (!seg) throw new ApiError(400, `Unknown segment ${body.segment} for ${c.id}.`);
808	      const userMsg = await say(body.content);
809	      const proposals = await saveProposals(user, seg.proposals, "segment");
810	      const reply = await postAgentMessage(user, type, params.id, seg.text, "segment", seg.citations.map((ci) => ci.ref).filter((ref) => signals.some((s) => s.id === ref)), body.segment);
811	      const messages: ChatMessage[] = [chatFromBackend(userMsg, [], label), { ...chatFromBackend(reply, [], label), proposalIds: proposals.map((p) => p.id) }];
812	      return { messages, proposals };
813	    }

