130	// ---------- cases ----------
131	/** Backend lifecycle per line (state + workflow + outcome) -> the UI's state and outcome. */
132	export function caseStateFromBackend(cv: Row): { state: Case["state"]; outcome: Case["outcome"] } {
133	  if (cv.state === "observed") return { state: "observed", outcome: null };
134	  if (cv.state === "confirmed") return { state: "decided", outcome: "confirmed" };
135	  if (cv.state === "rejected") return { state: "decided", outcome: cv.outcome === "merged" ? "merged" : "rejected" };
136	  if (cv.outcome) return { state: "decided", outcome: cv.outcome };
137	  return { state: cv.workflow ?? "new", outcome: null };
138	}
139	
140	function equipmentText(eq: Row | undefined): string {
141	  if (!eq?.listed) return "Not in the option list (German market)";
142	  const n = (xs?: unknown[]) => xs?.length ?? 0;
143	  const parts = [n(eq.standard) && `standard on ${n(eq.standard)} variants`, n(eq.optional) && `optional on ${n(eq.optional)}`, n(eq.absent) && `absent on ${n(eq.absent)}`, eq.removed && "removed vs. predecessor"].filter(Boolean);
144	  const price = eq.option_prices_eur?.length ? `; from ${Math.round(eq.option_prices_eur[0])} EUR` : "";
145	  return `${parts.join(", ") || "listed"}${price} (German option list)`;
146	}
147	
148	function perMarket(markets: Row, study: Row[]): MarketFigure[] {
149	  return Object.entries(markets ?? {})
150	    .map(([name, m]: [string, any]) => {
151	      const market = marketFromBackend(name);
152	      const total = (m.complaints ?? 0) + (m.wishes ?? 0) + (m.likes ?? 0);
153	      const worst = study.filter((s) => s.market === name).sort((a, b) => Number(a.normalized) - Number(b.normalized))[0];
154	      return {
155	        market,
156	        customers: m.customers ?? 0,
157	        complaints: m.complaints ?? 0,
158	        wishes: m.wishes ?? 0,
159	        likes: m.likes ?? 0,
160	        studyLabel: worst?.attribute,
161	        studyScore: worst ? `${round2(Number(worst.normalized))} of 1 (${worst.sheet})` : undefined,
162	        sentiment: total ? round2(Math.max(-1, Math.min(1, ((m.likes ?? 0) - (m.complaints ?? 0) - 0.5 * (m.wishes ?? 0)) / total))) : 0,
163	      };
164	    })
165	    .filter((m) => m.market !== "unknown" || m.customers > 0)
166	    .sort((a, b) => b.customers - a.customers);
167	}
