243	export function rowFromPage(page: Row, vehicle: string, profileId: string | null): Row {
244	  const cv = (page.vehicles as Row[]).find((v) => v.vehicle === vehicle) ?? page.vehicles[0] ?? { vehicle, state: "observed" };
