import { endpoints, type EndpointName } from "@/contracts";
import { handlers } from "@/mock/handlers";
import { db } from "@/mock/store";

// In-process sweep of the mock: every GET endpoint, for every persona, validated against the contract.
const d = db();
const firstCase = d.cases.find((c) => c.state !== "observed")!;
const req = d.requirements[0];
const ids: Record<string, string[]> = {
  caseBundle: d.cases.map((c) => c.id), requirementBundle: d.requirements.map((r) => r.id), requirementReplay: d.requirements.map((r) => r.id),
  exportCaseMd: [firstCase.id], caseSegments: d.cases.map((c) => c.id), shapeQuestions: d.cases.filter((c) => c.outcome === "confirmed").map((c) => c.id),
  ripple: d.ripples.map((r) => r.id), plan: ["G60", "F70", "G70"],
};
let ok = 0; const bad: string[] = [];
(async () => {
  for (const user of d.users) {
    for (const name of Object.keys(endpoints) as EndpointName[]) {
      const def = endpoints[name] as any;
      if (def.method !== "GET") continue;
      const keys = [...def.path.matchAll(/:([a-zA-Z]+)/g)].map((m: any) => m[1]);
      let paramSets: Record<string, string>[] = [{}];
      if (name === "messages") paramSets = [{ type: "case", id: firstCase.id }, { type: "requirement", id: req.id }];
      else if (keys.length) paramSets = (ids[name] ?? []).map((v) => ({ [keys[0]]: v }));
      for (const params of paramSets) {
        const query = name === "search" ? { q: "seat" } : name === "comments" ? { objectType: "case", objectId: firstCase.id } : {};
        try {
          const out = await (handlers as any)[name]({ params, query: def.query ? def.query.parse(query) : {}, body: undefined, user });
          const r = def.response.safeParse(out);
          if (r.success) ok++; else bad.push(`${name} ${JSON.stringify(params)} as ${user.id}: ${JSON.stringify(r.error.issues.slice(0, 2))}`);
        } catch (e: any) {
          if (e?.status && e.status < 500) ok++; else bad.push(`${name} ${JSON.stringify(params)} as ${user.id}: THROW ${e?.status ?? ""} ${e?.message}`);
        }
      }
    }
  }
  // replay integrity on the seed
  const fails: string[] = [];
  for (const r of d.requirements) {
    const rep: any = await (handlers as any).requirementReplay({ params: { id: r.id }, query: {}, body: undefined, user: d.users.find((u) => u.id === r.ownerId) ?? d.users[0] });
    for (const c of rep.integrity) if (!c.ok) fails.push(`${r.id} ${c.id}: ${c.failures.length} failures, e.g. ${c.failures[0]}`);
  }
  console.log(`users ${d.users.length}, cases ${d.cases.length}, requirements ${d.requirements.length}, signals ${d.signals.length}, ripples ${d.ripples.length}`);
  console.log(`GET sweep: ${ok} ok, ${bad.length} contract breaks`); bad.slice(0, 25).forEach((b) => console.log("  BREAK", b.slice(0, 400)));
  console.log(`replay integrity failures on seed: ${fails.length}`); fails.slice(0, 10).forEach((f) => console.log("  ", f.slice(0, 300)));
})();
EOF
